CREATE TYPE "Role" AS ENUM ('ADMIN');
CREATE TYPE "MessageStatus" AS ENUM ('NEW','READ','IN_PROGRESS','COMPLETED');
CREATE TABLE "User"("id" TEXT NOT NULL,"username" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'ADMIN',"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "User_username_key" ON "User"("username");
CREATE TABLE "SiteSettings"("id" TEXT NOT NULL,"siteName" TEXT NOT NULL,"description" TEXT NOT NULL,"logoUrl" TEXT,"faviconUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SiteSettings_pkey" PRIMARY KEY("id"));
CREATE TABLE "HeroContent"("id" TEXT NOT NULL,"title" TEXT NOT NULL,"subtitle" TEXT NOT NULL,"description" TEXT,"ctaText" TEXT,"ctaUrl" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "HeroContent_pkey" PRIMARY KEY("id"));
CREATE TABLE "AboutContent"("id" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"content" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AboutContent_pkey" PRIMARY KEY("id"));
CREATE TABLE "BotContent"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"version" TEXT,"imageUrl" TEXT,"features" JSONB,"commands" JSONB,"externalUrl" TEXT NOT NULL,"published" BOOLEAN NOT NULL DEFAULT true,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "BotContent_pkey" PRIMARY KEY("id"));
CREATE TABLE "Service"("id" TEXT NOT NULL,"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"shortDescription" TEXT NOT NULL,"fullDescription" TEXT NOT NULL,"icon" TEXT,"imageUrl" TEXT,"published" BOOLEAN NOT NULL DEFAULT true,"displayOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Service_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "Service_slug_key" ON "Service"("slug"); CREATE INDEX "Service_published_displayOrder_idx" ON "Service"("published","displayOrder");
CREATE TABLE "Project"("id" TEXT NOT NULL,"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"description" TEXT NOT NULL,"imageUrl" TEXT,"url" TEXT,"category" TEXT,"technologies" JSONB,"published" BOOLEAN NOT NULL DEFAULT true,"displayOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Project_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "Project_slug_key" ON "Project"("slug"); CREATE INDEX "Project_published_displayOrder_idx" ON "Project"("published","displayOrder");
CREATE TABLE "Promotion"("id" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"imageUrl" TEXT,"ctaText" TEXT,"ctaUrl" TEXT,"published" BOOLEAN NOT NULL DEFAULT true,"displayOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Promotion_pkey" PRIMARY KEY("id"));
CREATE TABLE "SocialLink"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"url" TEXT NOT NULL,"icon" TEXT,"enabled" BOOLEAN NOT NULL DEFAULT true,"displayOrder" INTEGER NOT NULL DEFAULT 0,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SocialLink_pkey" PRIMARY KEY("id")); CREATE UNIQUE INDEX "SocialLink_name_key" ON "SocialLink"("name");
CREATE TABLE "ContactMessage"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"whatsapp" TEXT NOT NULL,"service" TEXT NOT NULL,"message" TEXT NOT NULL,"status" "MessageStatus" NOT NULL DEFAULT 'NEW',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContactMessage_pkey" PRIMARY KEY("id")); CREATE INDEX "ContactMessage_status_createdAt_idx" ON "ContactMessage"("status","createdAt");
CREATE TABLE "SeoSettings"("id" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"keywords" TEXT,"canonical" TEXT,"ogImageUrl" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SeoSettings_pkey" PRIMARY KEY("id"));
CREATE TABLE "Media"("id" TEXT NOT NULL,"name" TEXT NOT NULL,"url" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER,"alt" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Media_pkey" PRIMARY KEY("id"));
